// Normaliza a entrada de qualquer canal (WhatsApp, teste manual, web).
// Contrato esperado no body:
//   { canal, remetente, texto, session_id? }

const b = $input.first().json.body ?? $input.first().json;

const canal = (b.canal ?? 'teste').toString();
const texto = (b.texto ?? b.message ?? '').toString().trim();

// --- Normalizacao de telefone -> so digitos, com DDI 55 ---
let tel = (b.remetente ?? b.from ?? b.telefone ?? '').toString();
tel = tel.replace(/\D/g, '');            // remove (), -, espaco, +
tel = tel.replace(/^0+/, '');            // zeros a esquerda
if (tel.length === 10 || tel.length === 11) tel = '55' + tel;  // sem DDI -> assume Brasil

// Brasil: celular tem 9 apos o DDD. Numeros antigos (8 digitos) precisam do 9.
if (tel.startsWith('55') && tel.length === 12) {
  const ddd = tel.slice(2, 4);
  const resto = tel.slice(4);
  if (Number(ddd) >= 11 && Number(ddd) <= 99) tel = '55' + ddd + '9' + resto;
}

if (!tel || tel.length < 12) {
  throw new Error('REMETENTE_INVALIDO');
}
if (!texto) {
  throw new Error('TEXTO_VAZIO');
}
if (texto.length > 1000) {
  throw new Error('TEXTO_LONGO');
}

return [{
  json: {
    canal,
    telefone: tel,
    pergunta: texto,
    session_id: (b.session_id ?? `${canal}:${tel}`).toString(),
    recebido_em: new Date().toISOString()
  }
}];

// Monta o contexto da sessao. TUDO que o agente pode ver e definido AQUI,
// no servidor. O LLM nunca escolhe de qual empresa os dados vem.

const auth = $input.first().json.response.dados;
const ent  = $('Normalizar Entrada').first().json;

// --- Selecao de empresa ---
// Multi-tenant: usuario pode pertencer a varias fazendas (fk_lista_empresas).
// Regra: usa a empresa padrao. Se houver mais de uma, o agente avisa o produtor
// que esta respondendo sobre a empresa X e como trocar (ver system prompt).
const empresas = auth.empresas ?? [];
const fkEmpresa = auth.empresa_padrao ?? empresas[0]?.fk_empresa;

if (!fkEmpresa) throw new Error('SEM_EMPRESA_ATIVA');

const empresaNome = empresas.find(e => e.fk_empresa === fkEmpresa)?.nome ?? 'sua fazenda';

// --- Data de hoje no fuso da fazenda ---
const tz = 'America/Sao_Paulo';
const agora = new Date();
const hoje = new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(agora); // YYYY-MM-DD
const diaSemana = new Intl.DateTimeFormat('pt-BR', { timeZone: tz, weekday: 'long' }).format(agora);

// --- Snapshot dos lotes ativos ---
// Injetado direto no system prompt: evita uma chamada de ferramenta em boa
// parte das conversas ("como estao meus lotes?" responde na hora).
const lotes = auth.snapshot_lotes ?? [];
const resumoLotes = lotes.length
  ? lotes.map(l => `- ${l.lote} (viveiro ${l.viveiro}, ${l.especie}, ${l.fase}, ${l.dias} dias)`).join('\n')
  : '(nenhum lote ativo no momento)';

return [{
  json: {
    fk_empresa: fkEmpresa,
    fk_user: auth.fk_user,
    nome: auth.nome ?? 'produtor',
    empresa_nome: empresaNome,
    multi_empresa: empresas.length > 1,
    empresas_nomes: empresas.map(e => e.nome).join(', '),
    permissoes: auth.permissoes ?? [],
    tem_financeiro: (auth.permissoes ?? []).includes('financeiro'),
    // chave de memoria: por usuario E por empresa (trocar de fazenda = novo contexto)
    session_key: `${ent.session_id}|${fkEmpresa}`,
    pergunta: ent.pergunta,
    canal: ent.canal,
    telefone: ent.telefone,
    hoje,
    dia_semana: diaSemana,
    resumo_lotes: resumoLotes,
    qtd_lotes: lotes.length
  }
}];

// Ajusta a saida do agente para o WhatsApp.
let texto = ($input.first().json.output ?? '').toString().trim();

// O modelo as vezes escapa para markdown mesmo instruido a nao usar.
texto = texto
  .replace(/^#{1,6}\s*/gm, '')      // titulos
  .replace(/\*\*(.+?)\*\*/g, '*$1*') // **negrito** -> *negrito* (padrao WhatsApp)
  .replace(/^\s*[\*\+]\s+/gm, '- ')  // bullets * / + -> -
  .replace(/```[a-z]*\n?/g, '')      // blocos de codigo
  .replace(/\n{3,}/g, '\n\n')        // linhas em branco em excesso
  .trim();

if (!texto) {
  texto = 'Nao consegui montar a resposta agora. Pode repetir a pergunta?';
}

// WhatsApp aguenta bem mais, mas resposta longa no celular nao e lida.
if (texto.length > 1200) {
  texto = texto.slice(0, 1180).trimEnd() + '...';
}

const ctx = $('Contexto').first().json;

return [{
  json: {
    ok: true,
    resposta: texto,
    // metadados para o adaptador do WhatsApp e para auditoria
    telefone: ctx.telefone,
    fk_user: ctx.fk_user,
    fk_empresa: ctx.fk_empresa,
    session_key: ctx.session_key,
    pergunta: ctx.pergunta,
    respondido_em: new Date().toISOString()
  }
}];

const motivo = $input.first().json.response?.motivo ?? 'nao_encontrado';

const mensagens = {
  nao_encontrado: 'Nao localizei seu numero no Meu Pescado. Peca ao responsavel da fazenda para cadastrar este WhatsApp no seu usuario, ou fale com nosso suporte.',
  inativo: 'Seu acesso esta inativo no momento. Fale com o responsavel da fazenda ou com nosso suporte.',
  sem_empresa: 'Seu usuario nao esta vinculado a nenhuma fazenda ativa. Fale com o responsavel da fazenda.'
};

return [{ json: { ok: false, resposta: mensagens[motivo] ?? mensagens.nao_encontrado } }];
